CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_delivery_dispatch_v2(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_result jsonb; v_verified jsonb; v_finalize jsonb;
BEGIN
 IF p_operation='backfill_delivery_status' THEN RETURN astra_ingestion_v1.backfill_delivery_status_v2(p_payload->>'run_id');
 ELSIF p_operation='backfill_status' THEN
  RETURN astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload)||jsonb_build_object('delivery',astra_ingestion_v1.backfill_delivery_status_v2(p_payload->>'run_id'));
 ELSIF p_operation='backfill_finalize' THEN RETURN astra_ingestion_v1.backfill_try_finalize_v2(p_payload->>'run_id');
 ELSIF p_operation='backfill_recover' THEN RETURN astra_ingestion_v1.backfill_recover_v2(p_payload);
 ELSIF p_operation='backfill_maintain' THEN RETURN astra_ingestion_v1.backfill_maintain_v2(COALESCE((p_payload->>'limit')::integer,2));
 ELSIF p_operation='backfill_plan_snapshot' THEN RETURN astra_ingestion_v1.backfill_plan_snapshot_v2(p_payload->>'run_id',COALESCE((p_payload->>'limit')::integer,500));
 ELSIF p_operation='backfill_seal_plan' THEN RETURN astra_ingestion_v1.backfill_seal_plan_v2(p_payload->>'run_id',(p_payload->>'expected_task_count')::bigint,p_payload->>'expected_plan_sha256',p_payload->'workflow_plan');
 ELSIF p_operation='backfill_verify' THEN
  v_result:=astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload);
  IF v_result->>'state'='committed' THEN
   v_verified:=astra_ingestion_v1.backfill_recheck_page_v2(v_result->>'task_id',(v_result->>'page_no')::integer);
   v_finalize:=astra_ingestion_v1.backfill_try_finalize_v2(p_payload#>>'{claim,run_id}');
   IF p_payload->'include_raw'='false'::jsonb THEN v_result:=v_result-'raw_body'; END IF;
   RETURN v_result||jsonb_build_object('verification',v_verified,'run_disposition',v_finalize);
  END IF;
  RETURN v_result;
 END IF;
 RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unsupported delivery operation';
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_dispatch_v2(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; p astra_ingestion_v1.backfill_pages_v2;
 v_now timestamptz:=clock_timestamp(); v_claim jsonb; v_owner text; v_lease int; v_supported jsonb; v_result jsonb;
 v_count int; v_hash text; v_raw text; v_cursor jsonb; v_state text; v_delay double precision; v_retry boolean; v_page int;
 v_parsed jsonb; v_source_rows jsonb; v_submitted_rows jsonb; v_source_cursor text; v_source_url text;
 v_members jsonb; v_contracts jsonb; v_symbols jsonb; v_child_scope jsonb; v_child_id text; v_record jsonb; v_group int; v_kind text;
 v_after_task text; v_after_page int; v_limit int; v_pages jsonb; v_last jsonb; v_more boolean;
 v_dependency record; v_capability_revision text; v_dependency_code text;
 v_not_before double precision; v_epoch double precision;
 v_fair_run text; v_fair_start integer; v_fair_pick record; v_fair_selected boolean;
BEGIN
 -- backfill_retained_reader_v2: invoked only after existing worker authentication.
 IF p_operation='backfill_reuse_commit' THEN RETURN astra_ingestion_v1.backfill_reuse_commit_v2(p_payload); END IF;
 -- backfill_retained_verify_v2: committed pointer, no fabricated live lease.
 IF p_operation='backfill_reuse_verify' THEN RETURN astra_ingestion_v1.backfill_reuse_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::integer); END IF;
 IF p_operation='backfill_feature_reuse_commit' THEN RETURN astra_ingestion_v1.backfill_feature_reuse_commit_v2(p_payload); END IF;
 IF p_operation='backfill_feature_reuse_verify' THEN RETURN astra_ingestion_v1.backfill_feature_reuse_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::int); END IF;
 IF p_operation='backfill_reuse_read' THEN RETURN astra_ingestion_v1.backfill_reuse_read_v2(p_payload); END IF;
 IF p_operation='backfill_breadth_material' THEN RETURN astra_ingestion_v1.backfill_breadth_material_v2(p_payload); END IF;
 IF p_operation='backfill_breadth_project' THEN RETURN astra_ingestion_v1.backfill_breadth_project_pending_v2(COALESCE((p_payload->>'limit')::integer,2)); END IF;
 IF p_operation='backfill_identity_material' THEN RETURN astra_ingestion_v1.backfill_identity_material_v2(p_payload); END IF;
 IF p_operation='backfill_identity_source_read' THEN RETURN astra_ingestion_v1.backfill_identity_source_read_v2(p_payload); END IF;
 IF p_operation='backfill_identity_source_commit' THEN RETURN astra_ingestion_v1.backfill_identity_source_commit_v2(p_payload); END IF;
 IF p_operation='backfill_identity_refresh' THEN RETURN jsonb_build_object('queued',astra_ingestion_v1.backfill_identity_refresh_pending_v2(COALESCE((p_payload->>'limit')::int,2))); END IF;
 IF p_operation='backfill_massive_archive_read' THEN RETURN astra_ingestion_v1.backfill_massive_archive_read_v2(p_payload);END IF;
 IF p_operation='backfill_massive_archive_commit' THEN RETURN astra_ingestion_v1.backfill_massive_archive_commit_v2(p_payload);END IF;
 IF p_operation='backfill_massive_archive_verify' THEN RETURN astra_ingestion_v1.backfill_massive_archive_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::int);END IF;
 IF p_operation='backfill_status' THEN
  -- backfill_runtime_status_asof_v2: report freshness uses its advertised v_now.
  -- Claim admission retains its existing live-clock checks unchanged.
  WITH fresh_workers AS MATERIALIZED (
   SELECT supported_kinds FROM astra_ingestion_v1.backfill_workers_v2
   WHERE observed_at>v_now-interval '10 minutes'
  )
  SELECT COALESCE(jsonb_agg(x),'[]') INTO v_result FROM (
   SELECT to_jsonb(r) || astra_ingestion_v1.backfill_identity_progress_v2(r.id) || jsonb_build_object(
    'members',(SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=r.id),
    'tasks',summary.tasks,
    'unsupported_pending_kinds',summary.unsupported_pending_kinds,
    'provider_dependencies',(SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]') FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=r.id),
    'next_retry_at',(SELECT min(next_retry_at) FROM astra_ingestion_v1.backfill_tasks_v2 st WHERE st.run_id=r.id AND status='RETRY_WAIT')) AS x
   FROM (SELECT * FROM astra_ingestion_v1.backfill_runs_v2
    WHERE p_payload->>'run_id' IS NULL OR id=p_payload->>'run_id' ORDER BY created_at DESC LIMIT 20) r
   CROSS JOIN LATERAL (
    WITH task_groups AS MATERIALIZED (
     SELECT family,kind,provider,status,count(*) tasks,sum(records_committed) records,max(last_progress_at) last_progress_at
     FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id GROUP BY family,kind,provider,status
    ), pending_kinds AS MATERIALIZED (
     SELECT DISTINCT kind FROM task_groups WHERE status IN ('PENDING','RETRY_WAIT')
    )
    SELECT (SELECT COALESCE(jsonb_agg(z),'[]') FROM task_groups z) tasks,
     (SELECT COALESCE(jsonb_agg(DISTINCT k.kind),'[]') FROM pending_kinds k
      WHERE NOT EXISTS(SELECT 1 FROM fresh_workers w WHERE w.supported_kinds ? k.kind)) unsupported_pending_kinds
   ) summary
   ORDER BY r.created_at DESC
  ) q;
  RETURN jsonb_build_object('runs',v_result,'observed_at',v_now);
 ELSIF p_operation='backfill_claim' THEN
  PERFORM astra_ingestion_v1.backfill_identity_discover_pending_v2();
  PERFORM astra_ingestion_v1.backfill_identity_refresh_pending_v2(2);
  v_now:=clock_timestamp();
  v_owner:=p_payload->>'worker_id'; v_supported:=p_payload->'supported_kinds';
  IF v_owner IS NULL OR v_owner !~ '^[A-Za-z0-9_.:-]{1,160}$' OR jsonb_typeof(v_supported) IS DISTINCT FROM 'array' OR jsonb_array_length(v_supported)>32
   OR COALESCE(length(p_payload->>'source_revision'),0) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded worker capabilities'; END IF;
  v_lease:=GREATEST(30,LEAST(COALESCE((p_payload->>'lease_seconds')::int,120),300));
  v_capability_revision:=COALESCE(p_payload->>'capability_revision',encode(sha256(convert_to(p_payload->>'source_revision'||':'||astra_ingestion_v1.rpc_canonical(v_supported),'UTF8')),'hex'));
  IF length(v_capability_revision) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid capability revision'; END IF;
  INSERT INTO astra_ingestion_v1.backfill_workers_v2(worker_id,source_revision,supported_kinds,capability_revision,observed_at)
   VALUES(v_owner,p_payload->>'source_revision',v_supported,v_capability_revision,v_now) ON CONFLICT(worker_id) DO UPDATE SET source_revision=EXCLUDED.source_revision,supported_kinds=EXCLUDED.supported_kinds,capability_revision=EXCLUDED.capability_revision,observed_at=v_now;
  -- Missing runtime configuration is one durable provider dependency; it does
  -- not consume attempts or request reservations for every waiting task.
  FOR v_dependency IN
   SELECT rr.id run_id,pp.provider FROM astra_ingestion_v1.backfill_runs_v2 rr CROSS JOIN (VALUES('Alpaca'),('Massive')) pp(provider)
   WHERE rr.status='ACTIVE' AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 st WHERE st.run_id=rr.id AND st.provider=pp.provider AND st.status IN ('PENDING','RETRY_WAIT','BLOCKED_EXTERNAL'))
  LOOP
   IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_workers_v2 w WHERE w.observed_at>v_now-interval '10 minutes'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(w.supported_kinds) k WHERE k LIKE lower(v_dependency.provider)||'_%')) THEN
    INSERT INTO astra_ingestion_v1.backfill_provider_dependencies_v2(run_id,provider,dependency,state,code,evidence)
     VALUES(v_dependency.run_id,v_dependency.provider,upper(v_dependency.provider)||'_WORKER_CREDENTIAL','BLOCKED_EXTERNAL','RUNTIME_CAPABILITY_UNAVAILABLE',jsonb_build_object('observed_at',v_now,'reason','No recently registered worker advertises this provider capability'))
     ON CONFLICT(run_id,provider) DO UPDATE SET state='BLOCKED_EXTERNAL',code=EXCLUDED.code,evidence=EXCLUDED.evidence,observed_at=v_now,resolved_at=NULL
      WHERE astra_ingestion_v1.backfill_provider_dependencies_v2.state='AVAILABLE';
   ELSE
    UPDATE astra_ingestion_v1.backfill_provider_dependencies_v2 d SET state='AVAILABLE',resolved_at=v_now,observed_at=v_now,
      evidence=d.evidence||jsonb_build_object('resolution','Changed configured worker capability observed','resolved_at',v_now)
     WHERE d.run_id=v_dependency.run_id AND d.provider=v_dependency.provider AND d.state='BLOCKED_EXTERNAL'
      AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_workers_v2 w WHERE w.observed_at>v_now-interval '10 minutes'
       AND (d.code='RUNTIME_CAPABILITY_UNAVAILABLE' OR w.worker_id IS DISTINCT FROM d.blocked_worker OR w.capability_revision IS DISTINCT FROM d.blocked_revision)
       AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(w.supported_kinds) k WHERE k LIKE lower(d.provider)||'_%'));
    UPDATE astra_ingestion_v1.backfill_tasks_v2 st SET status='PENDING',next_retry_at=v_now,error_code=NULL,error_message=NULL
     WHERE st.run_id=v_dependency.run_id AND st.provider=v_dependency.provider AND st.status='BLOCKED_EXTERNAL' AND st.error_code='MISSING_PROVIDER_CREDENTIAL'
      AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=st.run_id AND d.provider=st.provider AND d.state='AVAILABLE');
   END IF;
  END LOOP;
  -- Exhaustion stays an operational failure, never a provider-gap terminal result.
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='OPERATIONAL_ERROR',owner=NULL,lease_until=NULL,error_code='ATTEMPT_BUDGET_EXHAUSTED',error_message='Eight bounded attempts exhausted; implementation recovery must diagnose before requeue'
   WHERE status='RUNNING' AND lease_until<=v_now AND page_attempts>=8;

  -- backfill_family_fairness_hook_v2: one coherent queue, at most16 families and32 indexed candidate probes.
  SELECT id INTO v_fair_run FROM astra_ingestion_v1.backfill_runs_v2 WHERE status='ACTIVE' ORDER BY created_at,id LIMIT 1;
  IF v_fair_run IS NULL THEN RETURN NULL; END IF;
  INSERT INTO astra_ingestion_v1.backfill_family_turn_v2(run_id) VALUES(v_fair_run) ON CONFLICT(run_id) DO NOTHING;
  SELECT next_family_index INTO STRICT v_fair_start FROM astra_ingestion_v1.backfill_family_turn_v2 WHERE run_id=v_fair_run FOR UPDATE;
  v_fair_selected:=false;
  FOR v_fair_pick IN
   SELECT family,ordinality::integer family_index
   FROM unnest(ARRAY['REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06']) WITH ORDINALITY f(family,ordinality)
   ORDER BY mod(ordinality::integer-v_fair_start+16,16)
  LOOP
  -- backfill_due_recovery_priority_v2: recovery first, then the unchanged normal candidate.
  SELECT q.* INTO t FROM astra_ingestion_v1.backfill_tasks_v2 q JOIN astra_ingestion_v1.backfill_runs_v2 rr ON rr.id=q.run_id
   WHERE q.run_id=v_fair_run AND q.family=v_fair_pick.family
    AND q.status IN ('RETRY_WAIT','RUNNING') AND rr.status='ACTIVE' AND rr.fence=q.run_fence AND q.kind = ANY(ARRAY(SELECT jsonb_array_elements_text(v_supported)))
    AND q.next_retry_at<=v_now AND q.page_attempts<8
    AND (q.status IN ('PENDING','RETRY_WAIT') OR (q.status='RUNNING' AND q.lease_until<=v_now))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=q.run_id AND d.provider=q.provider AND d.state='BLOCKED_EXTERNAL')
    AND NOT EXISTS(SELECT 1 FROM unnest(q.dependencies) dep LEFT JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=dep
      WHERE d.id IS NULL OR d.run_id<>q.run_id OR d.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=q.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(q.dependencies) AND gap.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND (q.kind<>'derive_breadth' OR astra_ingestion_v1.backfill_breadth_ready_v2(q.id))
    AND (SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=v_fair_run)=3000 /* backfill_claim_member_count_once_v2 */
   ORDER BY q.priority,q.next_retry_at,q.created_at,q.id LIMIT 1 FOR UPDATE OF q;
  IF NOT FOUND THEN
  SELECT q.* INTO t FROM astra_ingestion_v1.backfill_tasks_v2 q JOIN astra_ingestion_v1.backfill_runs_v2 rr ON rr.id=q.run_id
   WHERE q.run_id=v_fair_run AND q.family=v_fair_pick.family
    AND q.status IN ('PENDING','RUNNING','RETRY_WAIT') AND rr.status='ACTIVE' AND rr.fence=q.run_fence AND q.kind = ANY(ARRAY(SELECT jsonb_array_elements_text(v_supported)))
    AND q.next_retry_at<=v_now AND q.page_attempts<8
    AND (q.status IN ('PENDING','RETRY_WAIT') OR (q.status='RUNNING' AND q.lease_until<=v_now))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=q.run_id AND d.provider=q.provider AND d.state='BLOCKED_EXTERNAL')
    AND NOT EXISTS(SELECT 1 FROM unnest(q.dependencies) dep LEFT JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=dep
      WHERE d.id IS NULL OR d.run_id<>q.run_id OR d.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=q.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(q.dependencies) AND gap.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND (q.kind<>'derive_breadth' OR astra_ingestion_v1.backfill_breadth_ready_v2(q.id))
    AND (SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=v_fair_run)=3000 /* backfill_claim_member_count_once_v2 */
   ORDER BY q.priority,q.next_retry_at,q.created_at,q.id LIMIT 1 FOR UPDATE OF q;
  END IF;
   IF FOUND THEN
    v_fair_selected:=true;
    UPDATE astra_ingestion_v1.backfill_family_turn_v2
     SET next_family_index=(v_fair_pick.family_index%16)+1,last_family=t.family,last_claimed_task_id=t.id,
      claim_turns=claim_turns+1,changed_at=v_now WHERE run_id=v_fair_run;
    EXIT;
   END IF;
  END LOOP;
  IF NOT v_fair_selected THEN RETURN NULL; END IF;

  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='RUNNING',owner=v_owner,generation=generation+1,lease_until=v_now+make_interval(secs=>v_lease),attempt_deadline=v_now+interval '5 minutes',
    page_limit=COALESCE(page_limit,CASE WHEN kind='massive_news' AND (cursor IS NULL OR cursor='null'::jsonb) THEN 100 ELSE astra_ingestion_v1.backfill_page_limit_cap_v2(kind) END),attempts=attempts+1,page_attempts=page_attempts+1,reserved_generation=NULL,reserved_page_no=NULL,reserved_at=NULL,source_revision=p_payload->>'source_revision'
   WHERE id=t.id RETURNING * INTO t;
  RETURN to_jsonb(t);
 END IF;
 v_claim:=p_payload->'claim';
 -- Readback never replays a mutation or requires a live lease; exact claim/run binding still applies.
 IF p_operation='backfill_verify' THEN
  SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=v_claim->>'id' AND run_id=v_claim->>'run_id';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Replacement task not found'; END IF;
  v_page:=COALESCE((p_payload->>'page_no')::int,t.page_no-1);
  SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND page_no=v_page;
  IF NOT FOUND THEN RETURN jsonb_build_object('state','not_committed','task_id',t.id,'page_no',v_page,'task_status',t.status,'next_page_no',t.page_no); END IF;
  RETURN jsonb_build_object('state','committed','task_id',t.id,'page_no',p.page_no,'body_sha256',p.body_sha256,
    'readback_sha256',encode(sha256(convert_to(p.raw_body,'UTF8')),'hex'),'records_sha256',p.records_sha256,'record_count',p.record_count,
    'next_cursor',p.cursor_out,'next_page_no',t.page_no,'task_status',t.status,'raw_body',p.raw_body,'request',p.request,'quality',p.quality,'adapter_version',p.adapter_version);
 END IF;
 -- A duplicate after a lost HTTP acknowledgement is an immutable matching-commit receipt, not a second write.
 IF p_operation='backfill_commit' AND v_claim->>'id' IS NOT NULL THEN
  SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=v_claim->>'id' AND page_no=(v_claim->>'page_no')::int;
  IF FOUND THEN
   IF p.run_id IS DISTINCT FROM v_claim->>'run_id' OR p.generation::text IS DISTINCT FROM v_claim->>'generation'
    OR p.run_fence::text IS DISTINCT FROM v_claim->>'run_fence' OR p.body_sha256 IS DISTINCT FROM p_payload->>'body_sha256' THEN
     RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Existing replacement receipt differs from original commit'; END IF;
   RETURN jsonb_build_object('state','already_committed','task_id',p.task_id,'page_no',p.page_no,'body_sha256',p.body_sha256,'record_count',p.record_count,'next_cursor',p.cursor_out);
  END IF;
 END IF;
 t:=astra_ingestion_v1.backfill_owned_v2(v_claim);
 IF p_operation='backfill_work' THEN RETURN to_jsonb(t);
 ELSIF p_operation='backfill_reserve' THEN
  IF t.reserved_generation=t.generation AND t.reserved_page_no=t.page_no THEN RETURN jsonb_build_object('state','already_reserved','task_id',t.id,'page_no',t.page_no); END IF;
  IF t.provider IN ('Alpaca','Massive') THEN
   v_epoch:=extract(epoch FROM v_now);
   SELECT next_request_at INTO STRICT v_not_before FROM astra_ingestion_v1.source_limits WHERE id=lower(t.provider) FOR UPDATE;
   IF v_not_before>v_epoch THEN
    UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='RETRY_WAIT',owner=NULL,lease_until=NULL,next_retry_at=to_timestamp(v_not_before),page_attempts=GREATEST(0,page_attempts-1) WHERE id=t.id;

    -- backfill_short_pacing_fairness_v2: a refused request has not served this family.
    -- The existing worker waits two seconds after request_deferred. Retaining
    -- this turn only for <=1 second is bounded; long Retry-After waits rotate.
    IF v_not_before>v_epoch AND v_not_before<=v_epoch+1.0 THEN
     UPDATE astra_ingestion_v1.backfill_family_turn_v2 ft
      SET next_family_index=array_position(ARRAY['REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06'],t.family),
       changed_at=v_now
      WHERE ft.run_id=t.run_id AND ft.last_claimed_task_id=t.id AND ft.last_family=t.family
       AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_runs_v2 rr
        WHERE rr.id=t.run_id AND rr.status='ACTIVE' AND rr.fence=t.run_fence);
    END IF;
    RETURN jsonb_build_object('state','request_deferred','task_id',t.id,'page_no',t.page_no,'next_retry_at',to_timestamp(v_not_before));
   END IF;
   -- backfill_paid_provider_pacing_v2: at most one reservation per second/provider; an existing later deadline still wins.
   UPDATE astra_ingestion_v1.source_limits SET next_request_at=v_epoch+1 WHERE id=lower(t.provider);
  END IF;
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET reserved_generation=generation,reserved_page_no=page_no,reserved_at=v_now,
    requests_reserved=requests_reserved+CASE WHEN provider IN ('Alpaca','Massive') THEN 1 ELSE 0 END WHERE id=t.id;
  UPDATE astra_ingestion_v1.backfill_runs_v2 SET requests_reserved=requests_reserved+CASE WHEN t.provider IN ('Alpaca','Massive') THEN 1 ELSE 0 END WHERE id=t.run_id;
  RETURN jsonb_build_object('state','reserved','task_id',t.id,'page_no',t.page_no,'query_scope',t.scope,'cursor',t.cursor,'lease_until',t.lease_until);

 ELSIF p_operation='backfill_defer' THEN
  -- backfill_adaptive_page_dispatch_v2: already authenticated, locked and fenced.
  IF p_payload->>'code'='SOURCE_PAGE_TOO_LARGE' THEN
   p_payload:=astra_ingestion_v1.backfill_adapt_page_v2(t,p_payload);
   t:=astra_ingestion_v1.backfill_owned_v2(v_claim);
  END IF;
  v_retry:=COALESCE((p_payload->>'retryable')::boolean,false);
  IF length(COALESCE(p_payload->>'code','')) NOT BETWEEN 1 AND 120 OR octet_length(COALESCE(p_payload->'evidence','{}')::text)>4194304 THEN
    RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded failure evidence'; END IF;
  v_delay:=GREATEST(2,COALESCE((p_payload->>'retry_after')::double precision,0),LEAST(3600,power(2,GREATEST(1,t.page_attempts))));
  IF v_delay IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision) OR extract(epoch FROM v_now)+v_delay>253402300799 THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retry-After must be a finite representable interval'; END IF;
  v_state:=CASE WHEN v_retry AND t.page_attempts<8 THEN 'RETRY_WAIT'
    WHEN p_payload->>'code' IN ('BLOCKED_EXTERNAL','AUTHENTICATION_FAILED','MISSING_CREDENTIAL','MISSING_PROVIDER_CREDENTIAL','PROVIDER_FORBIDDEN') THEN 'BLOCKED_EXTERNAL' ELSE 'OPERATIONAL_ERROR' END;
  IF t.provider IN ('Alpaca','Massive') AND (p_payload#>>'{evidence,http_status}'='429' OR p_payload->>'code' IN ('SOURCE_RATE_LIMIT','PROVIDER_RATE_LIMIT')) THEN
   UPDATE astra_ingestion_v1.source_limits SET next_request_at=GREATEST(next_request_at,extract(epoch FROM v_now)+v_delay) WHERE id=lower(t.provider);
  END IF;
  v_dependency_code:=p_payload#>>'{evidence,dependency}';
  IF t.provider IN ('Alpaca','Massive') AND v_dependency_code=upper(t.provider)||'_WORKER_CREDENTIAL' THEN
   v_state:='BLOCKED_EXTERNAL';
   SELECT capability_revision INTO v_capability_revision FROM astra_ingestion_v1.backfill_workers_v2 WHERE worker_id=t.owner;
   INSERT INTO astra_ingestion_v1.backfill_provider_dependencies_v2(run_id,provider,dependency,state,code,evidence,blocked_worker,blocked_revision)
    VALUES(t.run_id,t.provider,v_dependency_code,v_state,'MISSING_PROVIDER_CREDENTIAL',COALESCE(p_payload->'evidence','{}'),t.owner,v_capability_revision)
    ON CONFLICT(run_id,provider) DO UPDATE SET state=EXCLUDED.state,code=EXCLUDED.code,evidence=EXCLUDED.evidence,blocked_worker=EXCLUDED.blocked_worker,blocked_revision=EXCLUDED.blocked_revision,observed_at=v_now,resolved_at=NULL;
  END IF;
  INSERT INTO astra_ingestion_v1.backfill_exceptions_v2(run_id,task_id,page_no,generation,state,code,message,evidence,next_retry_at)
   VALUES(t.run_id,t.id,t.page_no,t.generation,v_state,p_payload->>'code',left(COALESCE(p_payload->>'message','Operation failed'),1000),COALESCE(p_payload->'evidence','{}'),CASE WHEN v_state='RETRY_WAIT' THEN v_now+make_interval(secs=>v_delay) END);
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status=v_state,owner=NULL,lease_until=NULL,next_retry_at=v_now+make_interval(secs=>v_delay),error_code=CASE WHEN v_dependency_code=upper(t.provider)||'_WORKER_CREDENTIAL' THEN 'MISSING_PROVIDER_CREDENTIAL' ELSE p_payload->>'code' END,error_message=left(p_payload->>'message',1000) WHERE id=t.id;
  RETURN jsonb_build_object('state',v_state,'task_id',t.id,'next_retry_at',CASE WHEN v_state='RETRY_WAIT' THEN v_now+make_interval(secs=>v_delay) END,'page_attempts',t.page_attempts);
 ELSIF p_operation='backfill_material' THEN
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET lease_until=LEAST(attempt_deadline,v_now+interval '120 seconds') WHERE id=t.id;
  v_after_task:=COALESCE(p_payload#>>'{after,task_id}',''); v_after_page:=COALESCE((p_payload#>>'{after,page_no}')::int,-1); v_limit:=GREATEST(1,LEAST(COALESCE((p_payload->>'limit')::int,2),4));
  SELECT COALESCE(jsonb_agg(x ORDER BY task_id,page_no),'[]') INTO v_pages FROM (
   SELECT pg.task_id,pg.page_no,jsonb_build_object('id',d.id,'kind',d.kind,'family',d.family,'provider',d.provider,'scope',d.scope,'cursor',pg.cursor_in) AS task,
    pg.raw_body,pg.body_sha256,pg.request,pg.record_count,pg.quality,pg.adapter_version
   FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=pg.task_id
   WHERE (pg.task_id=ANY(t.dependencies) OR pg.task_id IN (SELECT gap.id FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=t.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(t.dependencies))) AND pg.run_id=t.run_id AND (pg.task_id,pg.page_no)>(v_after_task,v_after_page)
   ORDER BY pg.task_id,pg.page_no LIMIT v_limit
  ) x;
  IF jsonb_array_length(v_pages)>0 THEN v_last:=v_pages->(jsonb_array_length(v_pages)-1); v_after_task:=v_last->>'task_id';v_after_page:=(v_last->>'page_no')::int; END IF;
  SELECT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 pg WHERE (pg.task_id=ANY(t.dependencies) OR pg.task_id IN (SELECT gap.id FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=t.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(t.dependencies))) AND pg.run_id=t.run_id AND (pg.task_id,pg.page_no)>(v_after_task,v_after_page)) INTO v_more;
  RETURN jsonb_build_object('pages',v_pages,'next_after',CASE WHEN v_more THEN jsonb_build_object('task_id',v_after_task,'page_no',v_after_page) END,'complete',NOT v_more,
    'dependency_states',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'status',status,'error_code',error_code)),'[]') FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=ANY(t.dependencies)));
 ELSIF p_operation<>'backfill_commit' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unsupported replacement operation';
 END IF;
 IF t.provider IN ('Alpaca','Massive') AND (t.reserved_generation IS DISTINCT FROM t.generation OR t.reserved_page_no IS DISTINCT FROM t.page_no) THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Page request must be durably reserved before dispatch'; END IF;
 v_raw:=p_payload->>'raw_body'; v_hash:=encode(sha256(convert_to(v_raw,'UTF8')),'hex');
 IF v_raw IS NULL OR octet_length(v_raw)>4194304 OR v_hash IS DISTINCT FROM p_payload->>'body_sha256'
  OR jsonb_typeof(p_payload->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'records')>100000
  OR (p_payload->>'http_status')::int<>200 OR NOT astra_ingestion_v1.backfill_request_valid_v2(t,p_payload->'request')
  OR length(COALESCE(p_payload->>'adapter_version','')) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Replacement source digest, request scope or page shape is invalid'; END IF;
 PERFORM astra_ingestion_v1.rpc_json_unique(v_raw::json);
 v_parsed:=v_raw::jsonb;
 IF t.kind IN ('alpaca_stock_bars','alpaca_option_bars') THEN
   SELECT COALESCE(jsonb_agg(b.value ORDER BY b.value::text),'[]') INTO v_source_rows
     FROM jsonb_each(COALESCE(NULLIF(v_parsed->'bars','null'::jsonb),'{}')) s CROSS JOIN LATERAL jsonb_array_elements(s.value) b;
 ELSIF t.kind='alpaca_reference' THEN v_source_rows:=jsonb_build_array(v_parsed);
 ELSIF t.kind='alpaca_option_contracts' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(COALESCE(NULLIF(v_parsed->'option_contracts','null'::jsonb),'[]'));
 ELSIF t.kind='alpaca_news' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(COALESCE(NULLIF(v_parsed->'news','null'::jsonb),'[]'));
 ELSIF t.kind='alpaca_actions' THEN
   SELECT COALESCE(jsonb_agg(b.value ORDER BY b.value::text),'[]') INTO v_source_rows
     FROM jsonb_each(COALESCE(NULLIF(v_parsed->'corporate_actions','null'::jsonb),'{}')) s CROSS JOIN LATERAL jsonb_array_elements(s.value) b;
 ELSIF t.provider='Massive' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(v_parsed->'results')='object' THEN jsonb_build_array(v_parsed->'results') ELSE COALESCE(NULLIF(v_parsed->'results','null'::jsonb),'[]') END);
 ELSE
   v_source_rows:=COALESCE(v_parsed->'rows',v_parsed->'records');
 END IF;
 IF t.provider IN ('Alpaca','Massive') THEN
   SELECT COALESCE(jsonb_agg(value->'source' ORDER BY (value->'source')::text),'[]') INTO v_submitted_rows FROM jsonb_array_elements(p_payload->'records');
 ELSE v_submitted_rows:=p_payload->'records'; END IF;
 IF v_source_rows IS DISTINCT FROM v_submitted_rows THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Normalized source rows do not match the original retained page'; END IF;
 v_count:=jsonb_array_length(p_payload->'records'); v_cursor:=NULLIF(p_payload->'next_cursor','null'::jsonb);
 IF t.provider='Alpaca' AND t.kind<>'alpaca_reference' THEN
  IF NOT (v_parsed ? 'next_page_token') THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Original source pagination field is missing'; END IF;
  IF NULLIF(v_parsed->'next_page_token','null'::jsonb) IS DISTINCT FROM v_cursor THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained source continuation differs from the proposed checkpoint'; END IF;
 ELSIF t.provider='Massive' THEN
  v_source_url:=v_parsed->>'next_url';v_source_cursor:=NULL;
  IF v_source_url IS NOT NULL THEN
   IF strpos(v_source_url,'https://api.massive.com'||(p_payload#>>'{request,path}')||'?')<>1
    AND strpos(v_source_url,'https://api.polygon.io'||(p_payload#>>'{request,path}')||'?')<>1 THEN
     RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Untrusted provider pagination origin or path'; END IF;
   SELECT astra_ingestion_v1.backfill_uri_component_v2(substr(kv,strpos(kv,'=')+1)) INTO v_source_cursor
    FROM unnest(string_to_array(split_part(v_source_url,'?',2),'&')) kv WHERE split_part(kv,'=',1)='cursor';
   IF v_source_cursor IS NULL THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Source continuation cursor missing'; END IF;
  END IF;
  IF v_source_cursor IS DISTINCT FROM v_cursor#>>'{}' THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained source continuation differs from the proposed checkpoint'; END IF;
 END IF;
 IF v_cursor IS NOT NULL AND (jsonb_typeof(v_cursor)<>'string' OR length(v_cursor#>>'{}') NOT BETWEEN 1 AND 8192 OR v_cursor IS NOT DISTINCT FROM t.cursor
  OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND cursor_in=v_cursor)) THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Replacement source pagination token is invalid or repeated'; END IF;
 v_state:=CASE WHEN v_cursor IS NOT NULL THEN 'PENDING' WHEN t.records_committed+v_count=0 THEN 'NO_DATA_RETURNED' ELSE 'INGESTED' END;
 IF v_cursor IS NULL AND p_payload->>'terminal_state' IN ('IDENTITY_OR_QUALITY_UNRESOLVED','NOT_APPLICABLE','PROVIDER_LIMITATION') THEN
   IF COALESCE(jsonb_array_length(p_payload->'quality'),0)=0 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='A terminal limitation requires retained evidence'; END IF;
   v_state:=p_payload->>'terminal_state';
 END IF;
 IF v_cursor IS NULL AND jsonb_array_length(COALESCE(p_payload->'quality','[]'))>0 AND v_state='INGESTED' THEN v_state:='IDENTITY_OR_QUALITY_UNRESOLVED'; END IF;
 INSERT INTO astra_ingestion_v1.backfill_pages_v2(task_id,page_no,run_id,generation,run_fence,provider,cursor_in,cursor_out,request,http_status,request_id,fetched_at,raw_body,body_sha256,records_sha256,record_count,source_bytes,quality,headers,adapter_version)
 VALUES(t.id,t.page_no,t.run_id,t.generation,t.run_fence,t.provider,t.cursor,v_cursor,p_payload->'request',200,left(p_payload->>'request_id',256),(p_payload->>'fetched_at')::timestamptz,v_raw,v_hash,
  encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(p_payload->'records'),'UTF8')),'hex'),v_count,octet_length(v_raw),COALESCE(p_payload->'quality','[]'),COALESCE(p_payload->'headers','{}'),p_payload->>'adapter_version');
 -- Durable contract enumeration admission is independently verified and reconciled by the same controller.
 IF t.kind='alpaca_option_contracts' THEN PERFORM astra_ingestion_v1.backfill_contract_enqueue_v2(t.id,t.page_no);END IF;
 PERFORM astra_ingestion_v1.backfill_owned_v2(v_claim);
 UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status=v_state,cursor=v_cursor,page_no=page_no+1,records_committed=records_committed+v_count,
  owner=NULL,lease_until=NULL,page_attempts=0,last_progress_at=v_now,next_retry_at=v_now,error_code=NULL,error_message=NULL WHERE id=t.id;
 UPDATE astra_ingestion_v1.backfill_runs_v2 SET pages_committed=pages_committed+1,records_committed=records_committed+v_count,source_bytes=source_bytes+octet_length(v_raw),last_progress_at=v_now WHERE id=t.run_id;
 IF v_state IN ('IDENTITY_OR_QUALITY_UNRESOLVED','NOT_APPLICABLE','PROVIDER_LIMITATION') THEN
  INSERT INTO astra_ingestion_v1.backfill_exceptions_v2(run_id,task_id,page_no,generation,state,code,message,evidence)
   VALUES(t.run_id,t.id,t.page_no,t.generation,v_state,v_state,'Retained source page has documented per-unit limitations',COALESCE(p_payload->'quality','[]'));
 END IF;
 RETURN jsonb_build_object('state','page_committed','task_id',t.id,'page_no',t.page_no,'task_status',v_state,'record_count',v_count,'body_sha256',v_hash,'next_cursor',v_cursor);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_plan_next_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '1s'
AS $function$
DECLARE
 r astra_ingestion_v1.backfill_runs_v2;
 m astra_ingestion_v1.backfill_members_v2;
 v_run text:=COALESCE(p_payload->>'run_id','fixed3000-20250901-20260731-v1-20261030');
 v_limit int:=GREATEST(1,LEAST(COALESCE((p_payload->>'member_limit')::int,1),5));
 v_next int; v_breadth int; v_phase text; v_added int:=0; v_members int:=0; v_expected bigint;
 v_calendar jsonb; v_month_calendar jsonb; v_target_dates jsonb; v_map jsonb; v_workflow jsonb; v_snapshot jsonb;
 v_scope jsonb; v_base jsonb; v_key text; v_source_id text; v_raw_id text; v_split_id text;
 v_anchor_count int; v_instrument int; v_asset text; v_month date; v_first date; v_last date;
 v_input date; v_entry jsonb; v_day date; v_family text; v_adjustment text; v_status text;
 v_count bigint; v_hash text; v_calendar_hash text; v_fallback boolean;
 v_after int; v_result jsonb; v_supported jsonb:=COALESCE(p_payload->'supported_kinds','[]'::jsonb);
BEGIN
 -- Same transaction lock as the authenticated existing RPC; no lease can be
 -- advanced by a competing planner between its insertions and checkpoint.
 PERFORM pg_advisory_xact_lock(706314020261028);
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=v_run FOR UPDATE;
 IF r.status<>'ACTIVE' THEN RETURN jsonb_build_object('state','PLANNING_PAUSED','run_id',r.id,'run_status',r.status,'plan_complete',false); END IF;
 IF r.metadata->'planning_complete'='true'::jsonb THEN
  RETURN jsonb_build_object('state','FULL_PLAN_SEALED','run_id',r.id,'plan_complete',true,
   'expected_task_count',r.metadata->'expected_static_task_count','expected_plan_sha256',r.metadata->'expected_plan_sha256');
 END IF;
 IF r.cohort_sha256<>'2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec'
 OR r.cohort_manifest_sha256<>'4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f'
 OR r.target_start<>'2025-09-01'::date OR r.target_end<>'2026-07-31'::date THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Planner accepts only the frozen replacement cohort and dates';
 END IF;
 SELECT count(*),encode(sha256(convert_to(string_agg(member_id,E'\n' ORDER BY selection_order,member_id),'UTF8')),'hex')
 INTO v_count,v_hash FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id;
 IF v_count<>3000 OR v_hash<>'a83310df6a6465ce8d37ffd5352095f6e38d91a3204afd8807fff39092cfd85e' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Frozen actual 3000-member list differs; selection cannot be reopened';
 END IF;
 SELECT jsonb_agg(jsonb_build_object('date',e->>'date','open',e->>'open','close',e->>'close') ORDER BY e->>'date')
 INTO v_calendar FROM jsonb_array_elements(r.scope#>'{calendar,sessions}') e;
 v_calendar_hash:=encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(v_calendar),'UTF8')),'hex');
 IF v_calendar IS NULL OR jsonb_array_length(v_calendar)<>290 OR v_calendar_hash<>'8483822a5553f0d270d87d1ff69c9a30d512d9ea8f660036664aebbf70053d49'
 OR r.scope->>'daily_support_start' IS DISTINCT FROM '2025-06-05'
 OR r.scope->>'intraday_support_start' IS DISTINCT FROM '2025-08-04' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Exact retained 290-session calendar and support history required';
 END IF;
 SELECT jsonb_agg(e->>'date' ORDER BY e->>'date') INTO v_target_dates FROM jsonb_array_elements(v_calendar) e
 WHERE e->>'date' BETWEEN '2025-09-01' AND '2026-07-31';
 v_workflow:=jsonb_build_object('version','fixed3000-plan-v2.1','target_start','2025-09-01','target_end','2026-07-31',
  'market_timezone','America/New_York','session_dates',v_target_dates,'cohort_classification','RETROSPECTIVE_FIXED_COHORT',
  'representative_policy','ONE_FROZEN_COMPANY_ONE_EXPLICIT_ANCHOR_SECURITY; ELIGIBILITY_UNKNOWN_UNTIL_EVIDENCED',
  'daily_support_start','2025-06-05','intraday_support_start','2025-08-04','calendar_sha256',v_calendar_hash,
  'formula_manifest_sha256','e0b0835ad53ef7b71d072184bbb1576b3cd8f514c523361fa31865f71a0c8a65',
  'families',jsonb_build_array('REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06'),
  'REF03',jsonb_build_object('mode','CONTINUOUS_AUDIT','scope','All replacement tasks/pages/exceptions/readbacks/recovery',
   'destination','astra_ingestion_v1.backfill_family_ref03_v2'),
  'P02',jsonb_build_object('mode','SHARED_P01_SOURCE_RETRIEVAL','sessions',jsonb_build_array('PRE','POST')),
  'event_policy','Retain all supplied action dates and boundary events; no ex-date-only archive restriction',
  'news_policy','All calendar dates, prefer Massive; separately retained Alpaca alternative if Massive worker configuration unavailable',
  'short_interest_policy','Settlement-date selection; actual publication/retrieval availability retained separately',
  'options_policy','Active and inactive underlying contracts; expiry Sep2025 through2099; dynamic individual-contract daily pages',
  'programme_expires_at',NULL);
 IF r.metadata->>'planner_version' IS NULL THEN
  v_snapshot:=astra_ingestion_v1.backfill_plan_snapshot_v2(r.id,500);
  IF v_snapshot->'more'='true'::jsonb THEN
   RETURN jsonb_build_object('state','SNAPSHOTTING_EXISTING_TASKS','plan_complete',false,'snapshot',v_snapshot);
  END IF;
  SELECT count(*) INTO v_expected FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id;
  r.metadata:=r.metadata||jsonb_build_object('planner_version','fixed3000-plan-v2.1','planner_phase','MEMBERS',
   'planner_next_selection_order',1,'planner_next_breadth_index',0,'planner_expected_static_count',v_expected,
   'planner_preexisting_static_count',v_expected,'workflow_plan',v_workflow);
 ELSIF r.metadata->>'planner_version'<>'fixed3000-plan-v2.1' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Existing planner version differs; retain and explicitly reconcile its checkpoint';
 END IF;
 v_next:=(r.metadata->>'planner_next_selection_order')::int;
 v_breadth:=(r.metadata->>'planner_next_breadth_index')::int;
 v_phase:=r.metadata->>'planner_phase';
 v_expected:=(r.metadata->>'planner_expected_static_count')::bigint;
 IF jsonb_typeof(v_supported)<>'array' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Worker supported kinds must be an explicit array'; END IF;
 v_fallback:=v_supported ? 'alpaca_news' AND NOT (v_supported ? 'massive_news');

 IF v_phase='MEMBERS' THEN
  -- backfill_planner_one_member_v2: commit one complete member before the next existing worker call.
  FOR m IN SELECT * FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id AND selection_order>=v_next
   ORDER BY selection_order LIMIT LEAST(v_limit,1)
  LOOP
   v_base:=jsonb_build_object('member_ids',jsonb_build_array(m.member_id),'symbols',jsonb_build_array(m.anchor_ticker),
    'symbol',m.anchor_ticker,'market_timezone','America/New_York','target_start','2025-09-01','target_end','2026-07-31',
    'identity_status','UNRESOLVED_PROVIDER_ANCHOR','asof','2026-08-03','cohort_classification','RETROSPECTIVE_FIXED_COHORT');
   v_key:=m.member_id||':';
   -- Daily raw/split series are fetched once per member for all required support.
   FOREACH v_adjustment IN ARRAY ARRAY['raw','split'] LOOP
    v_scope:=v_base||jsonb_build_object('timeframe','1Day','feed','sip','adjustment',v_adjustment,
     'start','2025-06-05T04:00:00Z','end','2026-08-01T03:59:59.999999Z','input_start','2025-06-05',
     'calendar',v_calendar,'daily_basis','ALPACA_PROVIDER_DAILY_NOT_ASSERTED_RTH','governing_date','MARKET_DATE',
     'support_history_policy','Observations before2025-09-01 retained as support history');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'daily-source:'||v_adjustment,'D02','Alpaca','alpaca_stock_bars',v_scope,'{}',20);
   END LOOP;
   v_raw_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'daily-source:raw');
   v_split_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'daily-source:split');
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:alpaca','REF01','Alpaca','alpaca_reference',
    v_base||jsonb_build_object('reference_policy','CURRENT_PROVIDER_IDENTIFIERS_NOT_HISTORICAL_PROOF'),'{}',10);
   SELECT count(*),min(instrument_key),min(alpaca_asset_id::text) INTO v_anchor_count,v_instrument,v_asset
    FROM reference.alpaca_fixed_window_instruments_v1 WHERE symbol=m.anchor_ticker AND alpaca_asset_id IS NOT NULL;
   -- Twelve monthly minute-source units cover Aug support plus all11 targetmonths.
   FOR v_month IN SELECT d::date FROM generate_series('2025-08-01'::date,'2026-07-01'::date,interval '1 month') d LOOP
    v_first:=GREATEST(v_month,'2025-08-04'::date);v_last:=(v_month+interval '1 month')::date-1;
    SELECT jsonb_agg(e ORDER BY e->>'date') INTO v_month_calendar FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date BETWEEN v_first AND v_last;
    v_scope:=v_base||jsonb_build_object('source_month',v_month::text,'target_start',v_first::text,'target_end',v_last::text,
     'input_start',v_first::text,'calendar',COALESCE(v_month_calendar,'[]'::jsonb),'feed','sip','timeframe','1Min','adjustment','raw',
     'start',to_char(v_first::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'end_exclusive',to_char((v_last+1)::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'support_history',v_last<'2025-09-01'::date,'governing_date','MARKET_SESSION',
     'shared_families',jsonb_build_array('P01','P02'),'identity_mapping_basis','POST_WINDOW_PROVIDER_ANCHOR_ONLY');
    IF v_anchor_count=1 THEN
     v_scope:=v_scope||jsonb_build_object('instrument_key',v_instrument,'alpaca_asset_id',v_asset,
      'reuse_policy','VERIFY_RETAINED_SOURCE_AND_ADMIT_ONLY_MISSING_OR_UNQUALIFIED_RANGES');
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'minutes:'||v_month::text,'P01','REUSE','retained_reuse',v_scope,'{}',30);
    ELSE
     v_scope:=v_scope||jsonb_build_object('end',to_char(((v_last+1)::timestamp AT TIME ZONE 'America/New_York')-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'retained_reference_state',CASE WHEN v_anchor_count=0 THEN 'NO_MATCHING_RETAINED_PROVIDER_ANCHOR' ELSE 'AMBIGUOUS_RETAINED_PROVIDER_ANCHOR' END);
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'minutes:'||v_month::text,'P01','Alpaca','alpaca_stock_bars',v_scope,'{}',30);
    END IF;
    IF v_month<'2025-09-01'::date THEN CONTINUE; END IF;
    v_source_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'minutes:'||v_month::text);
    FOR v_entry IN SELECT e FROM jsonb_array_elements(v_month_calendar) e LOOP
     v_day:=(v_entry->>'date')::date;
     v_scope:=v_base||jsonb_build_object('target_start',v_day::text,'target_end',v_day::text,'input_start',v_day::text,
      'source_month',v_month::text,'calendar',jsonb_build_array(v_entry),'governing_date','MARKET_SESSION',
      'formula_version','fixed3000-derived-v2.1','prefer_retained_formula_cache',true,
      'retained_formula_policy','Preserve original qualifying formula version and lineage when equivalent cache is available');
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'D01:'||v_day::text,'D01','DERIVED','derive_intraday',v_scope,ARRAY[v_source_id],160);
    END LOOP;
    -- The last60 actual preceding sessions, plus current month, are sufficient
    -- for all recovered daily horizons. Missing observations are never filled.
    SELECT min((x.e->>'date')::date) INTO v_input FROM (SELECT e FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date<v_month ORDER BY e->>'date' DESC LIMIT 60) x;
    SELECT jsonb_agg(e ORDER BY e->>'date') INTO v_month_calendar FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date BETWEEN v_input AND v_last;
    FOREACH v_family IN ARRAY ARRAY['D02','D03','D04','D05'] LOOP
     v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,'input_start',v_input::text,
      'source_month',v_month::text,'calendar',v_month_calendar,'governing_date','MARKET_SESSION',
      'formula_version','fixed3000-derived-v2.1','prefer_retained_formula_cache',true);
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||v_family||':'||v_month::text,v_family,'DERIVED','derive_daily',v_scope,ARRAY[v_raw_id,v_split_id],100);
    END LOOP;
    v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,'asof',v_month::text,
     'governing_date','REFERENCE_AS_OF','reference_policy','DATED_PROVIDER_SNAPSHOT_ATTRIBUTION_REMAINS_EXPLICIT');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:massive:'||v_month::text,'REF01','Massive','massive_reference',v_scope,'{}',40);
    v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,
     'start',to_char(v_month::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'end',to_char(((v_last+1)::timestamp AT TIME ZONE 'America/New_York')-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
     'governing_date','PUBLICATION_TIMESTAMP','include_weekends_holidays',true,'archive_scope','MASSIVE_ENTITLED_ARCHIVE',
     'permitted_alternative','alpaca_news');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'news:massive:'||v_month::text,'N01','Massive','massive_news',v_scope,'{}',50);
    IF v_fallback THEN
     v_scope:=v_scope||jsonb_build_object('archive_scope','ALPACA_ENTITLED_ARCHIVE',
      'alternative_reason','MASSIVE_WORKER_CONFIGURATION_UNAVAILABLE','does_not_complete_primary_archive',true,
      'primary_task_id',astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'news:massive:'||v_month::text));
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'news:alpaca:'||v_month::text,'N01','Alpaca','alpaca_news',v_scope,'{}',51);
    END IF;
   END LOOP;
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:massive:2026-07-31','REF01','Massive','massive_reference',
    v_base||jsonb_build_object('asof','2026-07-31','governing_date','REFERENCE_AS_OF'),'{}',40);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'dividends:massive','N02','Massive','massive_dividends',
    v_base||jsonb_build_object('governing_date','DECLARATION_EX_RECORD_PAYMENT_EFFECTIVE_SEPARATE','archive_date_filter','UNBOUNDED_PROVIDER_EVENT_HISTORY','retain_boundary_crossing_events',true),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'splits:massive','N03','Massive','massive_splits',
    v_base||jsonb_build_object('governing_date','EXECUTION_EFFECTIVE_DATE','archive_date_filter','UNBOUNDED_PROVIDER_EVENT_HISTORY','retain_boundary_crossing_events',true),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'actions:alpaca','N02','Alpaca','alpaca_actions',
    v_base||jsonb_build_object('start','2025-06-05','end',(r.created_at AT TIME ZONE 'America/New_York')::date::text,
     'governing_date','PROVIDER_PROCESS_DATE_WITH_SUPPLIED_ACTION_DATES_RETAINED','retain_boundary_crossing_events',true,
     'shared_families',jsonb_build_array('N02','N03')),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'short-volume','S01','Massive','massive_short_volume',
    v_base||jsonb_build_object('start','2025-09-01','end','2026-07-31','governing_date','REPORTING_DATE',
     'reporting_scope','PROVIDER_FINRA_OFF_EXCHANGE_NOT_TOTAL_MARKET'),'{}',60);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'short-interest','S02','Massive','massive_short_interest',
    v_base||jsonb_build_object('start','2025-09-01','end','2026-07-31','governing_date','SETTLEMENT_DATE',
     'publication_date_filter','NONE','retain_later_publications',true,'availability_policy','ACTUAL_PUBLICATION_WHEN_SUPPLIED_ELSE_RETRIEVAL_UPPER_BOUND'),'{}',60);
   FOREACH v_status IN ARRAY ARRAY['active','inactive'] LOOP
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'options:'||v_status,'CTX02','Alpaca','alpaca_option_contracts',
     v_base||jsonb_build_object('status',v_status,'expiration_start','2025-09-01','expiration_end','2099-12-31',
      'governing_date','CONTRACT_EXPIRY_REFERENCE_AND_DAILY_MARKET_DATE','include_adjusted_contracts',true,
      'historical_enumeration_completeness','UNKNOWN_UNTIL_PROVIDER_REFERENCE_EXHAUSTED'),'{}',70);
   END LOOP;
   v_next:=m.selection_order+1;v_members:=v_members+1;
  END LOOP;
  IF v_next>3000 THEN v_phase:='BREADTH'; END IF;
 ELSIF v_phase='BREADTH' THEN
  SELECT jsonb_object_agg(member_id,jsonb_build_object('symbol',anchor_ticker,'eligible',NULL) ORDER BY selection_order)
   INTO v_map FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id;
  v_after:=v_breadth;
  FOR v_entry IN SELECT e FROM jsonb_array_elements(v_calendar) e WHERE e->>'date' BETWEEN '2025-09-01' AND '2026-07-31'
   ORDER BY e->>'date' OFFSET v_after LIMIT v_limit
  LOOP
   v_day:=(v_entry->>'date')::date;
   v_scope:=jsonb_build_object('target_start',v_day::text,'target_end',v_day::text,'input_start',v_day::text,
    'market_timezone','America/New_York','calendar',jsonb_build_array(v_entry),'source_family','D03',
    'source_month',date_trunc('month',v_day)::date::text,'representative_security',v_map,
    'representative_policy',v_workflow->'representative_policy','governing_date','MARKET_SESSION',
    'formula_version','fixed3000-derived-v2.1','cohort_classification','RETROSPECTIVE_FIXED_COHORT');
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,'CTX06:'||v_day::text,'CTX06','DERIVED','derive_breadth',v_scope,'{}',250);
   v_breadth:=v_breadth+1;
  END LOOP;
  IF v_breadth=230 THEN v_phase:='SEAL'; END IF;
 ELSIF v_phase='SEAL' THEN
  v_snapshot:=astra_ingestion_v1.backfill_plan_snapshot_v2(r.id,500);
  IF v_snapshot->'more'='true'::jsonb THEN RETURN jsonb_build_object('state','SNAPSHOTTING_EXISTING_TASKS','plan_complete',false,'snapshot',v_snapshot); END IF;
  SELECT count(*),encode(sha256(convert_to(COALESCE(string_agg(task_id||':'||definition_sha256,E'\n' ORDER BY task_id COLLATE "C"),''),'UTF8')),'hex')
   INTO v_count,v_hash FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id;
  IF v_count<>v_expected THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Actual static plan count differs from transactionally admitted expected count'; END IF;
  v_result:=astra_ingestion_v1.backfill_seal_plan_v2(r.id,v_expected,v_hash,v_workflow);
  RETURN v_result||jsonb_build_object('run_id',r.id,'plan_complete',v_result->>'state'='FULL_PLAN_SEALED',
   'planned_members',3000,'next_selection_order',3001,'breadth_sessions',230);
 ELSE
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unknown persisted planner phase';
 END IF;
 v_expected:=v_expected+v_added;
 UPDATE astra_ingestion_v1.backfill_runs_v2 SET metadata=r.metadata||jsonb_build_object(
  'planner_phase',v_phase,'planner_next_selection_order',v_next,'planner_next_breadth_index',v_breadth,
  'planner_expected_static_count',v_expected,'workflow_plan',v_workflow,'planner_last_progress_at',clock_timestamp()),
  last_progress_at=CASE WHEN v_added>0 THEN clock_timestamp() ELSE last_progress_at END WHERE id=r.id;
 RETURN jsonb_build_object('state','PLAN_ADVANCED','run_id',r.id,'phase',v_phase,'plan_complete',false,
  'members_admitted_this_call',v_members,'planned_members',v_next-1,'next_selection_order',v_next,
  'breadth_sessions',v_breadth,'inserted_tasks',v_added,'expected_static_task_count',v_expected);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_reuse_commit_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; existing astra_ingestion_v1.backfill_pages_v2;
 s jsonb; pointer jsonb; quality jsonb; raw text; committed jsonb;
 child_scope jsonb; child_id text; children jsonb:='[]'; day text;
 query_start timestamptz; query_end timestamptz; gaps jsonb; parent_calendar jsonb;
BEGIN
 -- A lost acknowledgement is reconciled by reading the immutable receipt.
 SELECT * INTO existing FROM astra_ingestion_v1.backfill_pages_v2
  WHERE task_id=p_payload#>>'{claim,id}' AND page_no=(p_payload#>>'{claim,page_no}')::int;
 IF FOUND THEN
  IF existing.run_id IS DISTINCT FROM p_payload#>>'{claim,run_id}'
   OR existing.generation::text IS DISTINCT FROM p_payload#>>'{claim,generation}'
   OR existing.run_fence::text IS DISTINCT FROM p_payload#>>'{claim,run_fence}' THEN
    RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Reuse acknowledgement belongs to another claim'; END IF;
  RETURN jsonb_build_object('state','already_committed','task_id',existing.task_id,'page_no',existing.page_no,
   'body_sha256',existing.body_sha256,'record_count',existing.record_count,
   'reused_records',existing.raw_body::jsonb->'reused_records');
 END IF;
 t:=astra_ingestion_v1.backfill_owned_v2(p_payload->'claim');
 IF t.kind<>'retained_reuse' OR lower(t.provider)<>'reuse' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='A retained-source task is required'; END IF;
 s:=astra_ingestion_v1.backfill_reuse_read_v2(jsonb_build_object('claim',p_payload->'claim','mode','summary'));
 IF s->>'calendar_available' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Actual exchange calendar is required before planning retained-source gaps'; END IF;
 pointer:=(s-'rows'-'mode'-'state'-'next_after'-'has_more')||jsonb_build_object(
  'record_type','RETAINED_SOURCE_POINTER','reused_records',(s->>'record_count')::int,
  'source_original_unchanged',true,'new_market_rows_written',0);
 quality:=jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
  'reason',s->>'mapping_reason','scope','company_attribution','source_preserved',true),
  jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED','reason','UNKNOWN_PROVIDER_OBSERVATION_DENOMINATOR',
  'scope','observation_coverage','expected_bar_slots_are_not_a_trade_denominator',true));
 IF (s->>'record_count')::int<>(s->>'qualifying_profile_count')::int THEN
  quality:=quality||jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
    'reason','RETAINED_ROWS_WITH_UNQUALIFIED_PROVIDER_PROFILE','affected_records',
     (s->>'record_count')::int-(s->>'qualifying_profile_count')::int));
 END IF;
 IF (s->>'record_count')::int<>(s->>'valid_ohlcv_count')::int THEN
  quality:=quality||jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
    'reason','RETAINED_INVALID_OHLCV_REQUIRES_PROVIDER_REPAIR','affected_records',
     (s->>'record_count')::int-(s->>'valid_ohlcv_count')::int));
 END IF;
 raw:=astra_ingestion_v1.rpc_canonical(jsonb_build_object('rows',jsonb_build_array(pointer),
  'reused_records',(s->>'record_count')::int,'receipt_kind','RETAINED_SOURCE_POINTER'));
 committed:=astra_ingestion_v1.backfill_dispatch_v2('backfill_commit',jsonb_build_object(
  'claim',p_payload->'claim','raw_body',raw,'body_sha256',encode(sha256(convert_to(raw,'UTF8')),'hex'),
  'http_status',200,'request_id',NULL,'fetched_at',s->'observed_at',
  'request',jsonb_build_object('provider','REUSE','method','FIXED_RETAINED_READ',
    'source_relation',s->'source_relation','instrument_key',s->'instrument_key',
    'start',s->'start','end_exclusive',s->'end_exclusive'),
  'records',jsonb_build_array(pointer),'next_cursor',NULL,
  'terminal_state','IDENTITY_OR_QUALITY_UNRESOLVED','quality',quality,'headers','{}'::jsonb,
  'adapter_version','fixed3000-retained-pointer-v2.1'));

 -- Existing observations are never relabelled provider-empty. Missing retained
 -- ranges become real Alpaca work in the same transaction as the pointer.
 IF (s->>'record_count')::int=0 THEN gaps:='["WHOLE_SCOPE"]'::jsonb;
 ELSE
  SELECT COALESCE(jsonb_agg(d ORDER BY d),'[]') INTO gaps FROM (
   SELECT DISTINCT value d FROM jsonb_array_elements_text(
    COALESCE(s->'days_without_retained_rows','[]')||COALESCE(s->'days_with_unqualified_profile','[]')||
    COALESCE(s->'days_with_invalid_ohlcv','[]')) a(value)
  ) z;
 END IF;
 FOR day IN SELECT jsonb_array_elements_text(gaps) LOOP
  IF day='WHOLE_SCOPE' THEN
   query_start:=(t.scope->>'start')::timestamptz;
   query_end:=(t.scope->>'end_exclusive')::timestamptz-interval '1 microsecond';
   parent_calendar:=t.scope->'calendar';
  ELSE
   query_start:=(day::date+time '04:00') AT TIME ZONE 'America/New_York';
   query_end:=((day::date+time '20:00') AT TIME ZONE 'America/New_York')-interval '1 microsecond';
   SELECT COALESCE(jsonb_agg(x),'[]') INTO parent_calendar FROM jsonb_array_elements(t.scope->'calendar') x WHERE x->>'date'=day;
  END IF;
  child_scope:=jsonb_build_object('symbols',jsonb_build_array(t.scope->>'symbol'),
    'member_ids',t.scope->'member_ids','start',to_char(query_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'end',to_char(query_end AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'timeframe','1Min','feed','sip','adjustment','raw',
    'asof',COALESCE(t.scope->>'asof','2026-08-03'),'calendar',parent_calendar,
    'target_start',t.scope->'target_start','target_end',t.scope->'target_end',
    'market_timezone','America/New_York','identity_status','UNRESOLVED_PROVIDER_ANCHOR',
    'reuse_parent',t.id,'gap_reason',CASE WHEN day='WHOLE_SCOPE' THEN 'NO_RETAINED_ROWS' ELSE 'RETAINED_SESSION_MISSING_OR_UNQUALIFIED' END);
  child_id:='backfill-gap-'||encode(sha256(convert_to(t.run_id||':'||astra_ingestion_v1.rpc_canonical(child_scope),'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
   VALUES(child_id,t.run_id,'P01','Alpaca','alpaca_stock_bars',child_scope,t.priority+1,t.run_fence)
   ON CONFLICT(id) DO NOTHING;
  children:=children||jsonb_build_array(child_id);
 END LOOP;
 RETURN committed||jsonb_build_object('reused_records',(s->>'record_count')::int,
  'qualifying_reused_records',(s->>'qualifying_profile_count')::int,'provider_children',children,
  'new_market_rows_written',0);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.rpc_dispatch(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '10s'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
 v_headers jsonb; v_claims jsonb; v_token text; v_actor text; v_credential text; v_now double precision;
 v_result jsonb; v_spec jsonb; v_hash text; v_id text; v_key text; v_action text; v_claim jsonb; v_owned jsonb;
 v_job astra_ingestion_v1.jobs%ROWTYPE; v_part astra_ingestion_v1.partitions%ROWTYPE;
 v_start timestamptz; v_end timestamptz; v_cursor timestamptz; v_until timestamptz; v_symbol text;
 v_worker text; v_lease integer; v_phase text; v_status text; v_verification text; v_next double precision;
 v_raw text; v_parsed jsonb; v_record jsonb; v_payload_text text; v_previous text; v_count integer; v_bytes integer; v_page_token text;
 v_failures integer; v_delay double precision; v_proposed double precision; v_retry boolean; v_reason text; v_errcode text; v_errmessage text;
BEGIN
  -- A machine endpoint: an anonymous gateway context is necessary, but never
  -- sufficient. Independent scoped capability authentication happens here, so
  -- calling this private function directly cannot bypass the check.
  v_headers:=NULLIF(pg_catalog.current_setting('request.headers',true),'')::jsonb;
  v_claims:=NULLIF(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb;
  v_token:=v_headers->>'x-astra-ingestion-token';
  IF pg_catalog.current_setting('role',true) IS DISTINCT FROM 'anon'
     OR v_claims->>'role' IS DISTINCT FROM 'anon'
     OR (v_claims->>'sub') IS NOT NULL
     OR NULLIF(pg_catalog.current_setting('request.jwt.claim.sub',true),'') IS NOT NULL
     OR pg_catalog.current_setting('request.method',true) IS DISTINCT FROM 'POST'
     OR pg_catalog.jsonb_typeof(v_headers->'x-astra-ingestion-token') IS DISTINCT FROM 'string'
     OR v_token !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required';
  END IF;
  v_credential:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_token,'UTF8')),'hex');
  SELECT actor INTO v_actor FROM astra_ingestion_v1.runtime_credentials
    WHERE token_sha256=v_credential AND revoked_at IS NULL AND expires_at>pg_catalog.clock_timestamp();
  IF v_actor IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required'; END IF;
  IF p_operation IS NULL OR NOT (p_operation='health' OR (v_actor='api' AND p_operation IN ('list_jobs','get_job','submit_job','control_job','backfill_status','backfill_delivery_status'))
     OR (v_actor='worker' AND p_operation IN ('claim_next','reserve_request','commit_page','verification_material','finish_verification','fail_claim','backfill_status','backfill_claim','backfill_reserve','backfill_commit','backfill_defer','backfill_verify','backfill_material','backfill_work','backfill_relay_probe','backfill_relay_dispatch','backfill_massive_archive_read','backfill_massive_archive_commit','backfill_massive_archive_verify','backfill_identity_material','backfill_identity_source_read','backfill_identity_source_commit','backfill_identity_refresh','backfill_breadth_material','backfill_breadth_project','backfill_delivery_status','backfill_finalize','backfill_recover','backfill_maintain','backfill_plan_snapshot','backfill_seal_plan','backfill_plan_next','backfill_reuse_read','backfill_feature_reuse_commit','backfill_feature_reuse_verify','backfill_reuse_verify','backfill_reuse_commit'))) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='Operation is outside this capability';
  END IF;
  IF pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR pg_catalog.octet_length(p_payload::text)>8388608 THEN
    RAISE EXCEPTION USING ERRCODE='PT400',MESSAGE='A bounded operation object is required';
  END IF;
  -- Authentication precedes the global lock. Never accept SQL, identifiers,
  -- function names, destinations or schema choices from the caller.
  PERFORM pg_catalog.pg_advisory_xact_lock(706314020261028);
  IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.runtime_credentials WHERE token_sha256=v_credential AND actor=v_actor AND revoked_at IS NULL AND expires_at>pg_catalog.clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required';
  END IF;
  -- All mutating operations are in this exception subtransaction. An expected
  -- error rolls back its effects before the safe error envelope is returned.
  BEGIN
    v_now:=EXTRACT(EPOCH FROM pg_catalog.clock_timestamp());

    -- replacement_scope_admission_gate_v2: authenticated, serialized, immutable old scope.
    IF p_operation='submit_job' THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'error',pg_catalog.jsonb_build_object(
        'code','conflict','message','SUPERSEDED_BY_SCOPE_CHANGE: replacement fixed-cohort run owns new admission'));
    ELSIF p_operation='claim_next' THEN
      RETURN pg_catalog.jsonb_build_object('ok',true,'result',NULL);
    END IF;

    -- backfill_runtime_dispatch_v2: follows capability authentication and shared transaction lock.


    -- backfill_full_plan_hook_v2: bounded static admission, same authenticated worker.
    IF p_operation='backfill_plan_next' THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_plan_next_v2(p_payload));
    END IF;
    -- backfill_delivery_dispatch_hook_v2: same capability guard and transaction lock.
    IF p_operation IN ('backfill_status','backfill_verify','backfill_delivery_status','backfill_finalize','backfill_recover','backfill_maintain','backfill_plan_snapshot','backfill_seal_plan','backfill_plan_next') THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_delivery_dispatch_v2(p_operation,p_payload));
    END IF;

    -- backfill_managed_relay_hook_v2: after worker-only capability checks and existing global lock.
    IF p_operation IN ('backfill_relay_probe','backfill_relay_dispatch') THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_relay_v2(p_operation,p_payload));
    END IF;
    IF p_operation LIKE 'backfill_%' THEN
      RETURN pg_catalog.jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload));
    END IF;
    CASE p_operation
    WHEN 'health' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY[]::text[]) THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unexpected health parameters'; END IF;
      IF (SELECT version FROM astra_ingestion_v1.schema_info WHERE id=1) IS DISTINCT FROM 1 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Schema migration required'; END IF;
      v_result:=pg_catalog.jsonb_build_object('ready',true,'schema_version',1,'rpc_version',1);
    WHEN 'list_jobs' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['limit']) OR pg_catalog.jsonb_typeof(p_payload->'limit')<>'number' OR (p_payload->>'limit')!~'^[0-9]{1,3}$' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid list bound'; END IF;
      SELECT COALESCE(pg_catalog.jsonb_agg(astra_ingestion_v1.rpc_public_row(pg_catalog.to_jsonb(q)) ORDER BY q.created_at DESC),'[]'::jsonb)
        INTO v_result FROM (SELECT * FROM astra_ingestion_v1.jobs ORDER BY created_at DESC LIMIT GREATEST(1,LEAST((p_payload->>'limit')::integer,100))) q;
    WHEN 'get_job' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['job_id']) OR pg_catalog.jsonb_typeof(p_payload->'job_id')<>'string' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid job identifier'; END IF;
      v_result:=astra_ingestion_v1.rpc_job(p_payload->>'job_id');
    WHEN 'submit_job' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['spec','request_key']) OR pg_catalog.jsonb_typeof(p_payload->'request_key')<>'string'
        OR (p_payload->>'request_key')!~'^[A-Za-z0-9._:-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='A stable 8-128 character idempotency key is required'; END IF;
      v_spec:=astra_ingestion_v1.rpc_spec(p_payload->'spec');
      v_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(astra_ingestion_v1.rpc_canonical(v_spec),'UTF8')),'hex');
      SELECT * INTO v_job FROM astra_ingestion_v1.jobs WHERE request_key=p_payload->>'request_key';
      IF FOUND THEN
        IF v_job.scope_hash<>v_hash THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Idempotency key already belongs to another scope'; END IF;
        v_id:=v_job.id;
      ELSE
        v_id:=pg_catalog.gen_random_uuid()::text;
        INSERT INTO astra_ingestion_v1.jobs(id,request_key,scope_hash,name,spec,status,created_at,updated_at,deadline_at)
          VALUES(v_id,p_payload->>'request_key',v_hash,v_spec->>'name',astra_ingestion_v1.rpc_canonical(v_spec),'queued',v_now,v_now,v_now+(v_spec->>'deadline_seconds')::integer);
        v_start:=astra_ingestion_v1.rpc_timestamp(v_spec->>'start');v_end:=astra_ingestion_v1.rpc_timestamp(v_spec->>'end');
        FOR v_symbol IN SELECT value FROM pg_catalog.jsonb_array_elements_text(v_spec->'symbols') LOOP
          v_cursor:=v_start;
          WHILE v_cursor<v_end LOOP
            v_until:=LEAST(v_cursor+INTERVAL '24 hours',v_end);
            INSERT INTO astra_ingestion_v1.partitions(id,job_id,symbol,start_at,end_at,status)
              VALUES(pg_catalog.gen_random_uuid()::text,v_id,v_symbol,astra_ingestion_v1.rpc_time(v_cursor),astra_ingestion_v1.rpc_time(v_until),'pending');
            v_cursor:=v_until;
          END LOOP;
        END LOOP;
        PERFORM astra_ingestion_v1.rpc_event(v_id,'job_admitted',pg_catalog.jsonb_build_object('scope_hash',v_hash,'symbols',v_spec->'symbols'),v_now);
      END IF;
      v_result:=astra_ingestion_v1.rpc_job(v_id);
    WHEN 'control_job' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['job_id','action']) THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid control payload'; END IF;
      v_action:=p_payload->>'action';v_id:=p_payload->>'job_id';
      IF v_action NOT IN ('pause','resume','cancel') OR v_action IS NULL THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unsupported control'; END IF;
      SELECT * INTO v_job FROM astra_ingestion_v1.jobs WHERE id=v_id;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Job does not exist'; END IF;
      IF v_action='resume' THEN
        IF v_job.status<>'paused' OR v_job.deadline_at<=v_now THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Only an unexpired paused job can resume; quality holds remain in force'; END IF;
        UPDATE astra_ingestion_v1.jobs SET status='running',updated_at=v_now WHERE id=v_id;
        PERFORM astra_ingestion_v1.rpc_refresh(v_id,v_now);
      ELSIF v_action='pause' THEN
        IF v_job.status NOT IN ('queued','running','paused') THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Only queued or running jobs can pause'; END IF;
        UPDATE astra_ingestion_v1.jobs SET status='paused',updated_at=v_now WHERE id=v_id;
        UPDATE astra_ingestion_v1.partitions SET status=CASE WHEN status='verifying' THEN 'loaded' ELSE 'pending' END,
          owner=NULL,lease_until=NULL,generation=generation+1 WHERE job_id=v_id AND status IN ('running','verifying');
      ELSE
        IF v_job.status='completed' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='A completed job cannot be cancelled'; END IF;
        UPDATE astra_ingestion_v1.jobs SET status='cancelled',verification_status='cancelled',updated_at=v_now WHERE id=v_id;
        UPDATE astra_ingestion_v1.partitions SET status='cancelled',verification_status='cancelled',owner=NULL,lease_until=NULL,generation=generation+1
          WHERE job_id=v_id AND status IN ('pending','running','loaded','verifying');
      END IF;
      PERFORM astra_ingestion_v1.rpc_event(v_id,'job_'||v_action,'{}',v_now);v_result:=astra_ingestion_v1.rpc_job(v_id);
    WHEN 'claim_next' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['worker_id','lease_seconds']) OR pg_catalog.jsonb_typeof(p_payload->'worker_id') IS DISTINCT FROM 'string'
        OR (p_payload->>'worker_id')!~'^[A-Za-z0-9._:-]{1,128}$' OR pg_catalog.jsonb_typeof(p_payload->'lease_seconds') IS DISTINCT FROM 'number'
        OR (p_payload->>'lease_seconds')!~'^[0-9]{1,3}$' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded worker claim'; END IF;
      v_worker:=p_payload->>'worker_id';v_lease:=GREATEST(30,LEAST((p_payload->>'lease_seconds')::integer,300));
      FOR v_job IN SELECT * FROM astra_ingestion_v1.jobs WHERE status IN ('queued','running') AND deadline_at<=v_now LOOP
        UPDATE astra_ingestion_v1.partitions SET status='failed',verification_status='failed',owner=NULL,lease_until=NULL,generation=generation+1,error='Whole-job deadline exceeded'
          WHERE job_id=v_job.id AND status IN ('pending','running','loaded','verifying');
        UPDATE astra_ingestion_v1.jobs SET status='failed',verification_status='failed',error='Whole-job deadline exceeded',updated_at=v_now WHERE id=v_job.id;
        PERFORM astra_ingestion_v1.rpc_event(v_job.id,'deadline_exceeded','{}',v_now);
      END LOOP;
      SELECT p.* INTO v_part FROM astra_ingestion_v1.partitions p JOIN astra_ingestion_v1.jobs j ON j.id=p.job_id
        WHERE j.status IN ('queued','running') AND j.deadline_at>v_now AND p.next_attempt_at<=v_now
        AND (p.status IN ('pending','loaded') OR (p.status IN ('running','verifying') AND p.lease_until<=v_now))
        ORDER BY j.created_at,p.symbol,p.start_at LIMIT 1;
      IF NOT FOUND THEN v_result:='null';
      ELSE
        SELECT * INTO STRICT v_job FROM astra_ingestion_v1.jobs WHERE id=v_part.job_id;
        v_phase:=CASE WHEN v_part.status IN ('loaded','verifying') THEN 'verify' ELSE 'fetch' END;
        v_status:=CASE WHEN v_phase='verify' THEN 'verifying' ELSE 'running' END;
        UPDATE astra_ingestion_v1.partitions SET status=v_status,owner=v_worker,generation=generation+1,lease_until=v_now+v_lease WHERE id=v_part.id RETURNING * INTO v_part;
        UPDATE astra_ingestion_v1.jobs SET status='running',updated_at=v_now WHERE id=v_job.id;
        PERFORM astra_ingestion_v1.rpc_event(v_job.id,'partition_claimed',pg_catalog.jsonb_build_object('partition_id',v_part.id,'generation',v_part.generation,'phase',v_phase),v_now);
        v_result:=pg_catalog.to_jsonb(v_part)||pg_catalog.jsonb_build_object('phase',v_phase,'spec',v_job.spec::jsonb,'start',v_part.start_at,'end',v_part.end_at);
      END IF;
    WHEN 'reserve_request' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['claim']) THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid reservation payload'; END IF;
      v_claim:=p_payload->'claim';v_owned:=astra_ingestion_v1.rpc_owned(v_claim);
      SELECT * INTO v_part FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.partitions,v_owned->'partition');
      SELECT * INTO v_job FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.jobs,v_owned->'job');v_now:=(v_owned->>'now')::double precision;
      IF v_part.status<>'running' THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Not a fetch claim'; END IF;
      IF v_job.request_count>=(v_job.spec::jsonb->>'max_requests')::integer THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Whole-job provider request budget exhausted'; END IF;
      SELECT next_request_at INTO STRICT v_next FROM astra_ingestion_v1.source_limits WHERE id='alpaca';
      IF v_next>=v_job.deadline_at THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Provider not-before time exceeds this job deadline'; END IF;
      IF v_next>v_now THEN
        UPDATE astra_ingestion_v1.partitions SET status='pending',owner=NULL,lease_until=NULL,next_attempt_at=v_next WHERE id=v_part.id;
        -- Deliberately return, do not raise: pacing-release effects must commit.
        RETURN pg_catalog.jsonb_build_object('ok',false,'error',pg_catalog.jsonb_build_object('code','request_deferred','message','Shared provider pacing'));
      END IF;
      UPDATE astra_ingestion_v1.source_limits SET next_request_at=v_now+2 WHERE id='alpaca';
      UPDATE astra_ingestion_v1.jobs SET request_count=request_count+1,updated_at=v_now WHERE id=v_job.id;
      UPDATE astra_ingestion_v1.partitions SET request_count=request_count+1 WHERE id=v_part.id;
      PERFORM astra_ingestion_v1.rpc_owned(v_claim);v_result:='null';
    WHEN 'commit_page' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['claim','raw_body','request_id','records','next_page_token','response_sha256'])
        OR pg_catalog.jsonb_typeof(p_payload->'raw_body') IS DISTINCT FROM 'string'
        OR pg_catalog.jsonb_typeof(p_payload->'records') IS DISTINCT FROM 'array'
        OR pg_catalog.jsonb_typeof(p_payload->'response_sha256') IS DISTINCT FROM 'string'
        OR (p_payload->'request_id'<>'null'::jsonb AND (pg_catalog.jsonb_typeof(p_payload->'request_id')<>'string' OR pg_catalog.char_length(p_payload->>'request_id')>256)) THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Invalid source page payload';
      END IF;
      v_claim:=p_payload->'claim';v_owned:=astra_ingestion_v1.rpc_owned(v_claim);
      SELECT * INTO v_part FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.partitions,v_owned->'partition');
      SELECT * INTO v_job FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.jobs,v_owned->'job');v_now:=(v_owned->>'now')::double precision;
      IF v_part.status<>'running' OR v_part.next_page_token IS DISTINCT FROM v_claim->>'next_page_token' THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Page checkpoint moved'; END IF;
      IF v_part.request_count<=v_part.page_count THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Provider request was not reserved'; END IF;
      v_raw:=p_payload->>'raw_body';v_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_raw,'UTF8')),'hex');
      IF v_hash<>p_payload->>'response_sha256' THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Source receipt hash does not match'; END IF;
      v_parsed:=astra_ingestion_v1.rpc_parse_source(v_raw,v_part.symbol,v_part.start_at,v_part.end_at);
      IF v_parsed->'records'<>p_payload->'records' OR v_parsed->'next_page_token'<>p_payload->'next_page_token' THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Normalized records do not match the retained source response';
      END IF;
      v_page_token:=v_parsed->>'next_page_token';
      IF v_page_token IS NOT NULL AND (v_page_token IS NOT DISTINCT FROM v_part.next_page_token
          OR EXISTS(SELECT 1 FROM astra_ingestion_v1.receipts WHERE partition_id=v_part.id AND token_in=v_page_token)) THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Provider repeated a pagination token';
      END IF;
      v_count:=0;
      FOR v_record IN SELECT value FROM pg_catalog.jsonb_array_elements(v_parsed->'records') LOOP
        v_key:=(v_record->>'symbol')||'|'||(v_record->>'timestamp');v_payload_text:=astra_ingestion_v1.rpc_canonical(v_record);
        SELECT payload INTO v_previous FROM astra_ingestion_v1.records WHERE partition_id=v_part.id AND record_key=v_key;
        IF FOUND THEN
          IF v_previous::jsonb<>v_record THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Conflicting source values for existing record'; END IF;
        ELSE
          INSERT INTO astra_ingestion_v1.records(partition_id,record_key,payload) VALUES(v_part.id,v_key,v_payload_text);v_count:=v_count+1;
        END IF;
      END LOOP;
      v_bytes:=pg_catalog.octet_length(v_raw);
      IF v_job.record_count+v_count>(v_job.spec::jsonb->>'max_records')::integer THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Whole-job record budget exhausted'; END IF;
      IF v_job.receipt_bytes+v_bytes>33554432 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Whole-job retained source budget exceeds 32 MiB'; END IF;
      IF v_page_token IS NULL AND v_part.record_count+v_count=0 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Empty source coverage requires explicit review'; END IF;
      INSERT INTO astra_ingestion_v1.receipts(partition_id,page_no,token_in,token_out,request_id,raw_body,body_sha256,received_at)
        VALUES(v_part.id,v_part.page_count,v_part.next_page_token,v_page_token,p_payload->>'request_id',v_raw,v_hash,v_now);
      PERFORM astra_ingestion_v1.rpc_owned(v_claim);
      v_status:=CASE WHEN v_page_token IS NULL THEN 'loaded' ELSE 'pending' END;
      UPDATE astra_ingestion_v1.partitions SET status=v_status,next_page_token=v_page_token,page_count=page_count+1,record_count=record_count+v_count,
        owner=NULL,lease_until=NULL,last_progress_at=v_now,next_attempt_at=0,error=NULL WHERE id=v_part.id;
      UPDATE astra_ingestion_v1.jobs SET record_count=record_count+v_count,receipt_bytes=receipt_bytes+v_bytes,updated_at=v_now,last_progress_at=v_now WHERE id=v_job.id;
      PERFORM astra_ingestion_v1.rpc_event(v_job.id,'page_committed',pg_catalog.jsonb_build_object('partition_id',v_part.id,'page',v_part.page_count,'records',v_count,'receipt_sha256',v_hash),v_now);
      v_result:=pg_catalog.jsonb_build_object('records',v_count,'phase',CASE WHEN v_status='loaded' THEN 'verify' ELSE 'fetch' END);
    WHEN 'verification_material' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['claim']) THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid verification payload'; END IF;
      v_claim:=p_payload->'claim';v_owned:=astra_ingestion_v1.rpc_owned(v_claim);
      IF v_owned->'partition'->>'status'<>'verifying' THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Not a verification claim'; END IF;
      -- One SELECT gives both aggregates the same MVCC snapshot under READ COMMITTED.
      SELECT pg_catalog.jsonb_build_object(
        'receipts',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) ORDER BY r.page_no) FROM astra_ingestion_v1.receipts r WHERE r.partition_id=v_claim->>'id'),'[]'::jsonb),
        'records',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('record_key',r.record_key,'payload',r.payload::jsonb) ORDER BY r.record_key COLLATE "C") FROM astra_ingestion_v1.records r WHERE r.partition_id=v_claim->>'id'),'[]'::jsonb)) INTO v_result;
      IF pg_catalog.octet_length(v_result::text)>67108864 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification snapshot exceeds bounded response size'; END IF;
      PERFORM astra_ingestion_v1.rpc_owned(v_claim);
    WHEN 'finish_verification' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['claim','result']) OR pg_catalog.jsonb_typeof(p_payload->'result') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid verification result'; END IF;
      v_claim:=p_payload->'claim';v_owned:=astra_ingestion_v1.rpc_owned(v_claim);
      SELECT * INTO v_part FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.partitions,v_owned->'partition');
      SELECT * INTO v_job FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.jobs,v_owned->'job');v_now:=(v_owned->>'now')::double precision;
      IF v_part.status<>'verifying' THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Not a verification claim'; END IF;
      v_result:=p_payload->'result';
      IF NOT astra_ingestion_v1.rpc_keys(v_result,ARRAY['status','expected_count','actual_count','expected_hash','actual_hash',
          'missing_count','changed_count','unexpected_count','expected_duplicate_count','actual_duplicate_count',
          'missing_keys','changed_keys','unexpected_keys','expected_duplicate_keys','actual_duplicate_keys',
          'scope_hash','receipt_count','coverage_certification','verification_kind']) THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification must retain the complete comparison evidence';
      END IF;
      FOREACH v_key IN ARRAY ARRAY['expected_count','actual_count','missing_count','changed_count','unexpected_count',
          'expected_duplicate_count','actual_duplicate_count','receipt_count'] LOOP
        IF pg_catalog.jsonb_typeof(v_result->v_key) IS DISTINCT FROM 'number' OR (v_result->>v_key)!~'^[0-9]{1,6}$' THEN
          RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification counts must be bounded nonnegative integers';
        END IF;
      END LOOP;
      FOREACH v_key IN ARRAY ARRAY['expected_hash','actual_hash','scope_hash'] LOOP
        IF pg_catalog.jsonb_typeof(v_result->v_key) IS DISTINCT FROM 'string' OR (v_result->>v_key)!~'^[0-9a-f]{64}$' THEN
          RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification digests must be complete SHA256 values';
        END IF;
      END LOOP;
      FOREACH v_key IN ARRAY ARRAY['missing_keys','changed_keys','unexpected_keys','expected_duplicate_keys','actual_duplicate_keys'] LOOP
        IF pg_catalog.jsonb_typeof(v_result->v_key) IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification key examples must be bounded arrays';
        END IF;
        IF pg_catalog.jsonb_array_length(v_result->v_key)<>LEAST((v_result->>pg_catalog.replace(v_key,'_keys','_count'))::integer,20)
            OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(v_result->v_key) e(v)
            WHERE pg_catalog.jsonb_typeof(v)<>'string' OR pg_catalog.char_length(v#>>'{}')>128) THEN
          RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification key examples must be bounded arrays';
        END IF;
      END LOOP;
      -- Bind the worker's actual digest to the current retained target snapshot.
      SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(astra_ingestion_v1.rpc_canonical(
        COALESCE(pg_catalog.jsonb_agg(payload::jsonb ORDER BY record_key COLLATE "C"),'[]'::jsonb)),'UTF8')),'hex')
        INTO v_hash FROM astra_ingestion_v1.records WHERE partition_id=v_part.id;
      IF v_result->>'actual_hash' IS DISTINCT FROM v_hash THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification target digest changed before finalization';
      END IF;
      IF v_result->>'status' NOT IN ('passed','failed') OR v_result->>'status' IS NULL
        OR v_result->>'scope_hash' IS DISTINCT FROM v_job.scope_hash
        OR v_result->>'coverage_certification' IS DISTINCT FROM 'NOT_CERTIFIED'
        OR v_result->>'verification_kind' IS DISTINCT FROM 'source_to_target_exact'
        OR (v_result->>'receipt_count')::integer IS DISTINCT FROM v_part.page_count
        OR (v_result->>'actual_count')::integer IS DISTINCT FROM v_part.record_count THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Verification evidence does not match its immutable claim';
      END IF;
      IF v_result->>'status'='passed' AND ((v_result->>'expected_count')::integer IS DISTINCT FROM v_part.record_count
          OR v_result->>'expected_hash' IS DISTINCT FROM v_result->>'actual_hash'
          OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_each_text(v_result) e(k,v)
              WHERE k IN ('missing_count','changed_count','unexpected_count','expected_duplicate_count','actual_duplicate_count') AND v<>'0')) THEN
        RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Passing verification contains inconsistent counts or digests';
      END IF;
      INSERT INTO astra_ingestion_v1.verifications(partition_id,checked_at,result) VALUES(v_part.id,v_now,astra_ingestion_v1.rpc_canonical(v_result))
        ON CONFLICT(partition_id) DO UPDATE SET checked_at=excluded.checked_at,result=excluded.result;
      PERFORM astra_ingestion_v1.rpc_owned(v_claim);
      v_status:=CASE WHEN v_result->>'status'='passed' THEN 'verified' ELSE 'blocked' END;
      UPDATE astra_ingestion_v1.partitions SET status=v_status,verification_status=v_result->>'status',owner=NULL,lease_until=NULL,last_progress_at=v_now,
        error=CASE WHEN v_status='verified' THEN NULL ELSE 'Source-to-target reconciliation failed' END WHERE id=v_part.id;
      UPDATE astra_ingestion_v1.jobs SET last_progress_at=v_now,updated_at=v_now WHERE id=v_job.id;
      PERFORM astra_ingestion_v1.rpc_event(v_job.id,'verification_'||(v_result->>'status'),pg_catalog.jsonb_build_object('partition_id',v_part.id)||v_result,v_now);
      PERFORM astra_ingestion_v1.rpc_refresh(v_job.id,v_now);v_result:='null';
    WHEN 'fail_claim' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY['claim','code','message','retryable','retry_after','raw_response'])
        OR pg_catalog.jsonb_typeof(p_payload->'code') IS DISTINCT FROM 'string' OR pg_catalog.jsonb_typeof(p_payload->'message') IS DISTINCT FROM 'string'
        OR pg_catalog.jsonb_typeof(p_payload->'retryable') IS DISTINCT FROM 'boolean' OR pg_catalog.jsonb_typeof(p_payload->'retry_after') IS DISTINCT FROM 'number'
        OR pg_catalog.length(p_payload->>'retry_after')>30 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded failure payload'; END IF;
      v_claim:=p_payload->'claim';v_owned:=astra_ingestion_v1.rpc_owned(v_claim,true);
      SELECT * INTO v_part FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.partitions,v_owned->'partition');
      SELECT * INTO v_job FROM pg_catalog.jsonb_populate_record(NULL::astra_ingestion_v1.jobs,v_owned->'job');v_now:=(v_owned->>'now')::double precision;
      v_failures:=v_part.retry_count+1;v_delay:=(p_payload->>'retry_after')::double precision;
      IF v_delay<0 OR v_delay>253402300799 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid retry delay'; END IF;
      v_proposed:=v_now+GREATEST(v_delay,5.0*v_failures);v_retry:=(p_payload->>'retryable')::boolean AND v_failures<2 AND v_proposed<v_job.deadline_at;
      v_reason:=p_payload->>'message';
      IF (p_payload->>'retryable')::boolean AND v_proposed>=v_job.deadline_at THEN v_reason:=v_reason||'; provider wait exceeds the original job deadline'; END IF;
      v_reason:=pg_catalog.left((p_payload->>'code')||': '||v_reason,500);
      IF v_retry THEN v_status:=CASE WHEN v_part.status='verifying' THEN 'loaded' ELSE 'pending' END;v_verification:='pending';v_next:=v_proposed;
      ELSE v_status:=CASE WHEN (p_payload->>'retryable')::boolean THEN 'failed' ELSE 'blocked' END;v_verification:=v_status;v_next:=0; END IF;
      UPDATE astra_ingestion_v1.partitions SET status=v_status,verification_status=v_verification,
        retry_count=v_failures,next_attempt_at=v_next,error=v_reason WHERE id=v_part.id;
      IF v_delay>0 AND (p_payload->>'retryable')::boolean THEN UPDATE astra_ingestion_v1.source_limits SET next_request_at=GREATEST(next_request_at,LEAST(v_now+v_delay,253402300799)) WHERE id='alpaca'; END IF;
      IF p_payload->'raw_response'<>'null'::jsonb THEN
        IF pg_catalog.jsonb_typeof(p_payload->'raw_response')<>'string' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid rejected response'; END IF;
        v_raw:=p_payload->>'raw_response';IF pg_catalog.octet_length(v_raw)>2097152 THEN v_raw:='[Response exceeds retained-body bound]';END IF;
        INSERT INTO astra_ingestion_v1.rejections(id,partition_id,received_at,reason,raw_body,body_sha256)
          VALUES(pg_catalog.gen_random_uuid()::text,v_part.id,v_now,v_reason,v_raw,pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_raw,'UTF8')),'hex'));
      END IF;
      PERFORM astra_ingestion_v1.rpc_event(v_job.id,CASE WHEN v_retry THEN 'retry_scheduled' ELSE 'partition_'||v_status END,
        pg_catalog.jsonb_build_object('partition_id',v_part.id,'symbol',v_part.symbol,'reason',v_reason,'next_attempt_at',CASE WHEN v_next>0 THEN astra_ingestion_v1.rpc_time(pg_catalog.to_timestamp(v_next)) ELSE NULL END),v_now);
      PERFORM astra_ingestion_v1.rpc_owned(v_claim,true);
      UPDATE astra_ingestion_v1.partitions SET owner=NULL,lease_until=NULL WHERE id=v_part.id;
      PERFORM astra_ingestion_v1.rpc_refresh(v_job.id,v_now);v_result:='null';
    ELSE RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='Operation is outside this capability';
    END CASE;
    RETURN pg_catalog.jsonb_build_object('ok',true,'result',v_result);
  EXCEPTION
    WHEN SQLSTATE 'AI001' OR SQLSTATE 'AI002' OR SQLSTATE 'AI004' OR SQLSTATE 'AI005' THEN
      GET STACKED DIAGNOSTICS v_errcode=RETURNED_SQLSTATE,v_errmessage=MESSAGE_TEXT;
      RETURN pg_catalog.jsonb_build_object('ok',false,'error',pg_catalog.jsonb_build_object('code',
        CASE v_errcode WHEN 'AI001' THEN 'lease_lost' WHEN 'AI002' THEN 'quality_hold' WHEN 'AI004' THEN 'not_found' ELSE 'conflict' END,'message',v_errmessage));
    WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow OR invalid_datetime_format OR null_value_not_allowed THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'error',pg_catalog.jsonb_build_object('code','conflict','message','Invalid operation value'));
  END;
END $function$
